let selectedPosBookingId=null;
const posExtraItems={};
const posConsultations={};
let posCatalogOpen=false;
let posCatalogType='service';
let posCatalogDetail=null;
let posView='calendar';
let posMode='day';
let posDetailView='detail';
const posPaymentMethods={};
let posCustomItemOpen=false;
let posQrOpen=false;
let posCatalogSheetOpen=false;
let posCatalogSheetType='product';
let posCatalogSheetDetail=null;
let posCustomerProfileOpen=false;
const posCustomerEntitlements={};
const posAppliedEntitlements={};

function posStatusLabel(status){return status==='confirmed'?'Chờ đến':status==='checkedin'?'Đang phục vụ':status==='completed'?'Hoàn tất':'Đã hủy'}
function posStatusClass(status){return status==='confirmed'?'booked':status==='checkedin'?'serving':status==='completed'?'finished':'cancelled'}
function posStage(booking){
  const demoStages={'BK-1001':'pending_deposit','BK-1002':'in_service','BK-1003':'late','BK-1004':'completed'},key=booking.stage||demoStages[booking.id]||(booking.status==='checkedin'?'arrived':booking.status);
  const stages={pending_deposit:{key,label:'Chờ đặt cọc',tone:'warning',meta:'Cần xác nhận thanh toán'},confirmed:{key,label:'Đã xác nhận',tone:'booked',meta:'Sẵn sàng đón khách'},late:{key,label:'Đến trễ',tone:'critical',meta:'Trễ 12 phút'},arrived:{key,label:'Đã đến',tone:'arrived',meta:'Đang chờ KTV'},in_service:{key,label:'Đang phục vụ',tone:'serving',meta:'Đã check-in'},completed:{key,label:'Hoàn tất',tone:'finished',meta:'Đã thanh toán'},no_show:{key,label:'Không đến',tone:'muted',meta:'Cần liên hệ lại'},cancelled:{key,label:'Đã hủy',tone:'muted',meta:'Không còn giữ chỗ'}};
  return stages[key]||stages.confirmed;
}
function posCardMeta(booking){const stage=posStage(booking),service=getService(booking.service),person=getStaff(booking.staff);return '<span class="booking-stage '+stage.tone+'">'+stage.label+'</span><span class="booking-resource">'+person.name+' · '+service.duration+'′</span>'}
function posBookingPreview(booking){const customer=getCustomer(booking.customer),service=getService(booking.service),person=getStaff(booking.staff),stage=posStage(booking);return '<span class="booking-preview"><span class="booking-preview-head"><i class="booking-stage '+stage.tone+'">'+stage.label+'</i><b>'+booking.id+'</b></span><strong>'+customer.name+'</strong><span>'+customer.phone+(customer.email?' · '+customer.email:'')+'</span><span class="booking-preview-row"><b>'+booking.time+'–'+endTime(booking)+'</b><span>'+service.duration+' phút</span></span><span>'+service.name+'</span><span>KTV: <b>'+person.name+'</b></span>'+(booking.note?'<em>“'+booking.note+'”</em>':'')+'</span>'}
function posOverflowBadge(bookings,label,count=bookings.length){return '<button class="booking-overflow" onclick="event.stopPropagation()">+'+count+'<span class="booking-overflow-list"><strong>'+label+'</strong>'+bookings.map(booking=>{const customer=getCustomer(booking.customer),stage=posStage(booking);return '<i onclick="event.stopPropagation();selectPosBooking(\''+booking.id+'\')"><span><b>'+booking.time+' · '+customer.name+'</b><small>'+getService(booking.service).name+' · '+getStaff(booking.staff).name+'</small></span><em class="booking-stage '+stage.tone+'">'+stage.label+'</em></i>'}).join('')+'</span></button>'}
function posIso(date){return date.toISOString().slice(0,10)}
function posRange(){const anchor=new Date((document.getElementById('posDate').value||today())+'T12:00:00'),start=new Date(anchor),end=new Date(anchor);if(posMode==='week'){const offset=(anchor.getDay()+6)%7;start.setDate(anchor.getDate()-offset);end.setTime(start.getTime());end.setDate(end.getDate()+6)}else if(posMode==='month'){start.setDate(1);end.setMonth(start.getMonth()+1,0)}return{start:posIso(start),end:posIso(end)}}
function movePosDate(delta){const input=document.getElementById('posDate'),date=new Date((input.value||today())+'T12:00:00');if(posMode==='day')date.setDate(date.getDate()+delta);else if(posMode==='week')date.setDate(date.getDate()+delta*7);else date.setMonth(date.getMonth()+delta);input.value=posIso(date);selectedPosBookingId=null;renderPOS()}
function goPosToday(){document.getElementById('posDate').value=today();selectedPosBookingId=null;renderPOS()}
function setPosView(view){posView=view;selectedPosBookingId=null;renderPOS()}
function setPosMode(mode){posMode=mode;selectedPosBookingId=null;renderPOS()}
function openWalkIn(){openBooking();document.getElementById('modalTitle').textContent='Thêm khách vãng lai';document.querySelector('.modal-kicker').textContent='TIẾP NHẬN TẠI QUẦY';document.getElementById('fDate').value=document.getElementById('posDate').value||today();document.getElementById('fTime').value=new Date().toTimeString().slice(0,5)}
function openBookingAt(date,time,staffId){openBooking();document.getElementById('modalTitle').textContent='Tạo lịch tại '+time;document.getElementById('fDate').value=date;document.getElementById('fTime').value=time;document.getElementById('fStaff').value=staffId;document.getElementById('fAssignment').value='manual';toggleStaffMode()}
function selectPosBooking(id){selectedPosBookingId=id;posCatalogOpen=false;posDetailView='detail';renderPOS()}
function closePosDetail(){selectedPosBookingId=null;posCatalogOpen=false;posDetailView='detail';renderPosDetail();document.querySelectorAll('.pos-cal-event.selected').forEach(node=>node.classList.remove('selected'))}
function posCheckIn(id){changeStatus(id,'checkedin');selectedPosBookingId=id;renderPOS()}
function posStartCheckout(id){const booking=bookings.find(item=>item.id===id);if(booking&&booking.status==='confirmed')BookingRepository.updateStatus(database,id,'checkedin');refreshStore();selectedPosBookingId=id;render();notify('Đã mở hóa đơn từ lịch hẹn')}
function addPosItem(id,type){const items=posExtraItems[id]||(posExtraItems[id]=[]);if(type==='product')items.push({name:'Tinh dầu bưởi dưỡng tóc',meta:'Sản phẩm · SL 1',price:245000,kind:'SP'});else items.push({name:'Massage cổ vai gáy 20 phút',meta:'Dịch vụ thêm · KTV hiện tại',price:190000,kind:'DV'});renderPOS();notify('Đã thêm vào hóa đơn')}
function removePosItem(id,index){posExtraItems[id].splice(index,1);renderPOS()}
function completePosPayment(id){posQrOpen=false;const booking=bookings.find(item=>item.id===id);if(!booking)return;if(booking.status!=='completed')BookingRepository.updateStatus(database,id,'completed');refreshStore();render();selectedPosBookingId=id;notify('Thanh toán thành công · Lịch hẹn đã hoàn tất')}
function togglePosCatalog(open,type='service'){posCatalogOpen=open;posCatalogType=type;posCatalogDetail=null;posDetailView=open?'catalog':'detail';renderPosDetail()}
function setPosCatalogType(type){posCatalogType=type;posCatalogDetail=null;renderPosDetail()}
function showPosCatalogItemDetail(key){posCatalogDetail=key;renderPosDetail()}
function hidePosCatalogItemDetail(){posCatalogDetail=null;renderPosDetail()}
function openPosPayment(id){selectedPosBookingId=id;posDetailView='payment';renderPosDetail()}
function backToPosDetail(){posDetailView='detail';posCatalogOpen=false;renderPosDetail()}
function addPosPaymentMethod(id){const methods=posPaymentMethods[id]||(posPaymentMethods[id]=['cash']);methods.push('transfer');renderPosDetail()}
function removePosPaymentMethod(id,index){const methods=posPaymentMethods[id]||(posPaymentMethods[id]=['cash']);if(methods.length>1)methods.splice(index,1);renderPosDetail()}
function setPosPaymentMethod(id,index,value){const methods=posPaymentMethods[id]||(posPaymentMethods[id]=['cash']);methods[index]=value;renderPosDetail()}
function openPosCustomItem(){posCustomItemOpen=true;renderPosDetail()}
function closePosCustomItem(){posCustomItemOpen=false;renderPosDetail()}
function savePosCustomItem(id){const name=document.getElementById('customItemName')?.value.trim(),price=Number(document.getElementById('customItemPrice')?.value||0),type=document.getElementById('customItemType')?.value||'product';if(!name){notify('Vui lòng nhập tên dịch vụ hoặc sản phẩm');return}(posExtraItems[id]||(posExtraItems[id]=[])).push({name,meta:type==='service'?'Dịch vụ tùy ý':'Sản phẩm tùy ý',price,kind:type==='service'?'DV':'SP'});posCustomItemOpen=false;renderPOS();notify('Đã thêm '+name)}
function submitPosPayment(id){const methods=posPaymentMethods[id]||(posPaymentMethods[id]=['cash']);if(methods.some(method=>method!=='cash')){posQrOpen=true;renderPosDetail()}else completePosPayment(id)}
function closePosQr(){posQrOpen=false;renderPosDetail()}
function openPosCatalogSheet(type='product'){posCatalogSheetOpen=true;posCatalogSheetType=type;posCatalogSheetDetail=null;renderPosDetail()}
function closePosCatalogSheet(){posCatalogSheetOpen=false;posCatalogSheetDetail=null;renderPosDetail()}
function setPosCatalogSheetType(type){posCatalogSheetType=type;posCatalogSheetDetail=null;renderPosDetail()}
function showPosCatalogDetail(key){posCatalogSheetDetail=key;renderPosDetail()}
function hidePosCatalogDetail(){posCatalogSheetDetail=null;renderPosDetail()}
function removePosCustomerProfile(){document.querySelectorAll('body > .customer-profile-backdrop').forEach(node=>node.remove())}
function mountPosCustomerProfile(booking){removePosCustomerProfile();const markup=renderPosCustomerProfile(booking);if(markup)document.body.insertAdjacentHTML('beforeend',markup)}
function openPosCustomerProfile(){posCustomerProfileOpen=true;renderPosDetail()}
function closePosCustomerProfile(){posCustomerProfileOpen=false;removePosCustomerProfile();renderPosDetail()}
function openCatalogFromCustomerProfile(){
  posCustomerProfileOpen=false;
  removePosCustomerProfile();
  posCatalogOpen=true;
  posCatalogType='service';
  posCatalogDetail=null;
  posDetailView='catalog';
  renderPosDetail()
}
function usePosCustomerEntitlement(customerId,key,bookingId){
  const usage=posCustomerEntitlements[customerId]||(posCustomerEntitlements[customerId]={wellness:3,skin:4});
  if(!usage[key]){notify('Quyền lợi này đã sử dụng hết');return}
  usage[key]-=1;
  const isWellness=key==='wellness';
  posAppliedEntitlements[bookingId]={key,label:isWellness?'Gội đầu dưỡng sinh':'Combo phục hồi làn da',customerId};
  posCustomerProfileOpen=false;removePosCustomerProfile();posDetailView='payment';renderPOS();notify('Đã trừ 1 buổi · Dịch vụ trong hóa đơn còn 0 ₫')
}
function addPosCatalogSheetItem(id,key){const catalog={serum:{name:'Serum phục hồi B5',meta:'Sản phẩm · 30 ml',price:469000,kind:'SP'},grapefruit:{name:'Tinh dầu bưởi dưỡng tóc',meta:'Sản phẩm · 50 ml',price:245000,kind:'SP'},basicSkin:{name:'Chăm sóc da cơ bản',meta:'Dịch vụ · 60 phút',price:650000,kind:'DV'},hairWash:{name:'Gội đầu thư giãn',meta:'Dịch vụ · 30 phút',price:350000,kind:'DV'},skinCombo:{name:'Combo phục hồi làn da · 5 buổi',meta:'Gói dịch vụ · 5 dịch vụ con',price:2800000,kind:'GÓI'},giftCard:{name:'Thẻ tài khoản Premium',meta:'Gift card · Giá trị 5.000.000 ₫',price:4700000,kind:'THẺ'}};(posExtraItems[id]||(posExtraItems[id]=[])).push(catalog[key]);posCatalogSheetOpen=false;posCatalogSheetDetail=null;renderPOS();notify('Đã thêm '+catalog[key].name)}
function savePosConsultation(id){const note=document.getElementById('posConsultNote')?.value.trim();posConsultations[id]=note||'Khách quan tâm chăm sóc tại nhà và duy trì liệu trình.';notify('Đã lưu nội dung tư vấn');renderPosDetail()}
function addCatalogItem(id,kind){
  const returnToPayment=posDetailView==='payment';
  const catalog={product:{name:'Serum phục hồi B5 · 30 ml',meta:'SP-B5-30 · Còn 12 tại chi nhánh',price:469000,kind:'SP'},service:{name:'Massage cổ vai gáy · 20 phút',meta:'DV thêm · KTV hiện tại',price:190000,kind:'DV'},package:{name:'Combo chăm sóc da · 5 buổi',meta:'Gói dịch vụ · Hạn 180 ngày',price:2800000,kind:'GÓI'},card:{name:'Thẻ Premium · 5 triệu',meta:'Thẻ tài khoản · Hạn 12 tháng',price:4700000,kind:'THẺ'}};
  (posExtraItems[id]||(posExtraItems[id]=[])).push(catalog[kind]);posCatalogOpen=false;posDetailView=returnToPayment?'payment':'detail';renderPOS();notify('Đã thêm '+catalog[kind].name+' vào đơn')
}

function renderPOS(){
  const page=document.getElementById('pos');if(!page)return;
  const dateInput=document.getElementById('posDate');if(!dateInput.value)dateInput.value=today();
  document.querySelectorAll('[data-pos-view]').forEach(button=>button.classList.toggle('active',button.dataset.posView===posView));
  document.querySelectorAll('[data-pos-mode]').forEach(button=>button.classList.toggle('active',button.dataset.posMode===posMode));
  const staffFilter=document.getElementById('posStaffFilter');if(staffFilter.options.length===1)staffFilter.insertAdjacentHTML('beforeend',staff.map(person=>'<option value="'+person.id+'">'+person.name+'</option>').join(''));
  const range=posRange(),statusFilter=document.getElementById('posStatusFilter').value,staffId=staffFilter.value,location=document.getElementById('posLocationFilter').value,query=document.getElementById('posSearch').value.trim().toLocaleLowerCase('vi');
  const all=bookings.filter(item=>item.date>=range.start&&item.date<=range.end&&item.status!=='cancelled'&&(!location||location==='q1')).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));
  const visible=all.filter(item=>{const customer=getCustomer(item.customer),service=getService(item.service),haystack=[customer.name,customer.phone,customer.email,item.id,service.name].filter(Boolean).join(' ').toLocaleLowerCase('vi');return(!statusFilter||posStage(item).key===statusFilter)&&(!staffId||item.staff===staffId)&&(!query||haystack.includes(query))});
  const waiting=all.filter(item=>item.status==='confirmed').length,serving=all.filter(item=>item.status==='checkedin').length,completed=all.filter(item=>item.status==='completed').length;
  const busyStaff=new Set(all.filter(item=>item.status==='checkedin').map(item=>item.staff)).size,freeStaff=Math.max(0,staff.length-busyStaff),totalBeds=4,totalRooms=3,freeBeds=Math.max(0,totalBeds-serving),freeRooms=Math.max(0,totalRooms-serving);
  const periodLabel=posMode==='day'?'trong ngày':posMode==='week'?'trong tuần':'trong tháng';
  document.getElementById('posSummary').innerHTML='<div><span>Tổng lịch</span><b>'+all.length+'</b><small>'+periodLabel+'</small></div><div><span>Chờ đến</span><b>'+waiting+'</b><small>cần tiếp nhận</small></div><div><span>Đang phục vụ</span><b>'+serving+'</b><small>tại '+serving+' vị trí</small></div><div><span>Đã hoàn tất</span><b>'+completed+'</b><small>'+Math.round((completed/Math.max(all.length,1))*100)+'% lịch trong kỳ</small></div><div class="resource-metric"><span>Giường trống</span><b>'+freeBeds+'/'+totalBeds+'</b><small>có thể nhận khách</small></div><div class="resource-metric"><span>Phòng trống</span><b>'+freeRooms+'/'+totalRooms+'</b><small>sẵn sàng sử dụng</small></div><div class="resource-metric"><span>Nhân viên trống</span><b>'+freeStaff+'/'+staff.length+'</b><small>'+busyStaff+' đang phục vụ</small></div>';
  const days=posMode==='day'?1:posMode==='week'?7:30,bookedMinutes=all.reduce((sum,item)=>sum+getService(item.service).duration,0);document.getElementById('posCapacity').textContent='Công suất '+Math.round(bookedMinutes/(staff.length*9*60*days)*100)+'% · '+staff.length+' KTV';
  const periodText=range.start===range.end?new Date(range.start+'T12:00:00').toLocaleDateString('vi-VN'):(new Date(range.start+'T12:00:00').toLocaleDateString('vi-VN')+' – '+new Date(range.end+'T12:00:00').toLocaleDateString('vi-VN'));
  dateInput.title='Khoảng đang xem: '+periodText;
  if(posView==='list')document.getElementById('posTimeline').innerHTML=renderPosList(visible,periodText);
  else if(posMode!=='day')document.getElementById('posTimeline').innerHTML=renderPosPeriod(visible,range);
  else renderPosDay(visible,all,dateInput.value,staffId);
  if(selectedPosBookingId&&!visible.some(item=>item.id===selectedPosBookingId))selectedPosBookingId=null;renderPosDetail();
}

function renderPosDay(visible,all,date,staffId){
  const shownStaff=staffId?staff.filter(person=>person.id===staffId):staff,startMinute=540,slotMinutes=30,slotHeight=52,slotCount=18;
  const timeAxis=Array.from({length:slotCount},(_,index)=>{const value=startMinute+index*slotMinutes;return '<div class="pos-cal-time">'+String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0')+'</div>'}).join('');
  const headers='<div class="pos-cal-corner">GMT+7</div>'+shownStaff.map(person=>'<div class="pos-cal-staff"><span class="staff-avatar">'+person.name.split(' ').map(part=>part[0]).slice(-2).join('')+'</span><div><b>'+person.name+'</b><small>'+all.filter(item=>item.staff===person.id&&item.status!=='completed').length+' lịch còn lại · 09:00–18:00</small></div></div>').join('');
  const columns=shownStaff.map(person=>{const slots=Array.from({length:slotCount},(_,index)=>{const value=startMinute+index*slotMinutes,time=String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0');return '<button class="pos-cal-slot" onclick="openBookingAt(\''+date+'\',\''+time+'\',\''+person.id+'\')"><span>＋</span></button>'}).join('');const groups=Object.values(visible.filter(item=>item.staff===person.id).reduce((result,item)=>{const bucket=Math.floor(minutes(item.time)/30)*30,key=String(bucket);(result[key]||(result[key]=[])).push(item);return result},{}));const events=groups.map(group=>{const item=group[0],customer=getCustomer(item.customer),service=getService(item.service),stage=posStage(item),top=((Math.floor(minutes(item.time)/30)*30-startMinute)/slotMinutes)*slotHeight,height=Math.max(72,(service.duration/slotMinutes)*slotHeight-4),extra=group.slice(1);return '<div class="pos-cal-event '+stage.tone+(item.id===selectedPosBookingId?' selected':'')+'" style="top:'+top+'px;height:'+height+'px" role="button" tabindex="0" onclick="selectPosBooking(\''+item.id+'\')"><span class="event-time">'+item.time+'–'+endTime(item)+'</span><b>'+customer.name+'</b><small>'+service.name+'</small><span class="event-footer">'+posCardMeta(item)+'</span>'+posBookingPreview(item)+(extra.length?posOverflowBadge(extra,group.length+' lịch của '+person.name+' trong khung '+item.time):'')+'</div>'}).join('');return '<div class="pos-cal-column">'+slots+events+'</div>'}).join('');
  document.getElementById('posTimeline').innerHTML='<div class="pos-calendar" style="--staff-count:'+shownStaff.length+'"><div class="pos-cal-header">'+headers+'</div><div class="pos-cal-scroll"><div class="pos-cal-body"><div class="pos-cal-axis">'+timeAxis+'</div>'+columns+'</div></div></div>';
}

function renderPosList(items,periodText){
  if(!items.length)return '<div class="pos-empty"><b>Chưa có lịch hẹn</b><span>'+periodText+'</span><button class="btn secondary" onclick="openBooking()">＋ Tạo lịch hẹn</button></div>';
  return '<div class="pos-list-head"><b>'+items.length+' lịch hẹn</b><span>'+periodText+'</span></div><div class="pos-list-table"><div class="pos-list-row header"><span>Thời gian</span><span>Khách hàng</span><span>Dịch vụ</span><span>Nhân viên</span><span>Trạng thái</span></div>'+items.map(item=>{const customer=getCustomer(item.customer),service=getService(item.service),person=getStaff(item.staff),stage=posStage(item);return '<button class="pos-list-row" onclick="selectPosBooking(\''+item.id+'\')"><span><b>'+item.time+'</b><small>'+new Date(item.date+'T12:00:00').toLocaleDateString('vi-VN')+'</small></span><span><b>'+customer.name+'</b><small>'+customer.phone+'</small></span><span><b>'+service.name+'</b><small>'+service.duration+' phút</small></span><span>'+person.name+'</span><span><i class="booking-stage '+stage.tone+'">'+stage.label+'</i><small>'+stage.meta+'</small></span></button>'}).join('')+'</div>';
}

function renderPosPeriod(items,range){
  const days=[],cursor=new Date(range.start+'T12:00:00'),last=new Date(range.end+'T12:00:00');while(cursor<=last){days.push(posIso(cursor));cursor.setDate(cursor.getDate()+1)}
  if(posMode==='week')return renderPosWeek(items,days);
  return '<div class="pos-period-grid month">'+days.map(day=>{const dayItems=items.filter(item=>item.date===day),shown=dayItems.slice(0,2),extra=dayItems.slice(2),label=new Date(day+'T12:00:00').toLocaleDateString('vi-VN',{weekday:'short',day:'2-digit',month:'2-digit'});return '<section class="pos-period-day '+(day===today()?'today':'')+'" onclick="openBookingAt(\''+day+'\',\'10:00\',\''+(staff[0]?.id||'')+'\')"><header><b>'+label+'</b><span>'+dayItems.length+' lịch</span></header><div>'+shown.map(item=>{const customer=getCustomer(item.customer),service=getService(item.service),stage=posStage(item);return '<button class="pos-period-card '+stage.tone+'" onclick="event.stopPropagation();selectPosBooking(\''+item.id+'\')"><b>'+item.time+' · '+customer.name+'</b><span>'+service.name+'</span><small>'+getStaff(item.staff).name+'</small><i class="booking-stage '+stage.tone+'">'+stage.label+'</i>'+posBookingPreview(item)+'</button>'}).join('')+(extra.length?'<span class="month-overflow">'+posOverflowBadge(dayItems,dayItems.length+' lịch ngày '+label,extra.length)+'</span>':'')+'</div></section>'}).join('')+'</div>';
}

function renderPosWeek(items,days){
  const startMinute=9*60,slotMinutes=30,slotHeight=48,slotCount=18;
  const headers='<div class="pos-week-corner">GMT+7</div>'+days.map(day=>{const date=new Date(day+'T12:00:00');return '<div class="pos-week-day-head '+(day===today()?'today':'')+'"><span>'+date.toLocaleDateString('vi-VN',{weekday:'short'})+'</span><b>'+date.getDate()+'</b><small>'+items.filter(item=>item.date===day).length+' lịch</small></div>'}).join('');
  const timeAxis=Array.from({length:slotCount},(_,index)=>{const value=startMinute+index*slotMinutes;return '<div class="pos-week-time">'+String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0')+'</div>'}).join('');
  const columns=days.map(day=>{const slots=Array.from({length:slotCount},(_,index)=>{const value=startMinute+index*slotMinutes,time=String(Math.floor(value/60)).padStart(2,'0')+':'+String(value%60).padStart(2,'0');return '<button class="pos-week-slot" onclick="openBookingAt(\''+day+'\',\''+time+'\',\''+(staff[0]?.id||'')+'\')" aria-label="Tạo lịch '+time+' ngày '+day+'"><span>＋ '+time+'</span></button>'}).join('');const groups=Object.values(items.filter(item=>item.date===day).reduce((result,item)=>{const bucket=Math.floor(minutes(item.time)/30)*30,key=String(bucket);(result[key]||(result[key]=[])).push(item);return result},{}));const events=groups.map(group=>{const item=group[0],customer=getCustomer(item.customer),service=getService(item.service),stage=posStage(item),top=((Math.floor(minutes(item.time)/30)*30-startMinute)/slotMinutes)*slotHeight,height=Math.max(46,(service.duration/slotMinutes)*slotHeight-3),extra=group.slice(1);return '<div class="pos-week-event '+stage.tone+'" style="top:'+top+'px;height:'+height+'px"><button class="pos-week-event-main" onclick="event.stopPropagation();selectPosBooking(\''+item.id+'\')"><b>'+item.time+' · '+customer.name+'</b><span>'+service.name+'</span><i class="booking-stage '+stage.tone+'">'+stage.label+'</i></button>'+posBookingPreview(item)+(extra.length?'<button class="booking-overflow" onclick="event.stopPropagation()">+'+extra.length+'<span class="booking-overflow-list"><strong>'+group.length+' lịch trong khung '+item.time+'</strong>'+group.map(booking=>{const previewCustomer=getCustomer(booking.customer),previewStage=posStage(booking);return '<i onclick="event.stopPropagation();selectPosBooking(\''+booking.id+'\')"><span><b>'+booking.time+' · '+previewCustomer.name+'</b><small>'+getService(booking.service).name+' · '+getStaff(booking.staff).name+'</small></span><em class="booking-stage '+previewStage.tone+'">'+previewStage.label+'</em></i>'}).join('')+'</span></button>':'')+'</div>'}).join('');return '<div class="pos-week-column '+(day===today()?'today':'')+'">'+slots+events+'</div>'}).join('');
  return '<div class="pos-week-calendar"><div class="pos-week-header">'+headers+'</div><div class="pos-week-scroll"><div class="pos-week-body"><div class="pos-week-axis">'+timeAxis+'</div>'+columns+'</div></div></div>';
}

function posLineItem(item,index,booking){const isBase=index<0,service=isBase?getService(booking.service):null,name=isBase?service.name:item.name,price=isBase?service.price:item.price,meta=isBase?(booking.time+'–'+endTime(booking)+' ('+service.duration+'′) · Chọn nhân viên'):item.meta;return '<div class="reference-line"><span class="reference-line-accent"></span><div><b>'+name+'</b><span>'+meta+'</span></div><div class="reference-qty"><button>−</button><b>1</b><button>＋</button><button class="trash" '+(isBase?'disabled':'onclick="removePosItem(\''+booking.id+'\','+index+')"')+'>⌫</button></div><strong>'+money(price)+'</strong></div>'}
